/** Rust: `browser::gating::PageAction` */
export type PageAction =
  | { do: "read_page" }
  | ({ do: "scroll" } & { dy: number; })
  | ({ do: "click" } & { target: Target; })
  | ({ do: "type" } & { target: Target; text: string; })
  | ({ do: "select" } & { target: Target; value: string; })
  | ({ do: "submit" } & { target: Target; })
  | ({ do: "navigate" } & { url: string; })
  | ({ do: "search" } & { query: string; });

/**
 * Page metadata for clipper templates (author, description, published date, site, keywords).
 * Rust: `bridge::protocol::PageMeta`
 */
export interface PageMeta {
  author: string | null;
  description: string | null;
  published: string | null;
  site: string | null;
  keywords: string[] | null;
}

/** Rust: `clip::paste::PasteAs` */
export type PasteAs =
  | "original"
  | "plain"
  | "markdown"
  | "trimmed";

/** Rust: `win_mcp::PendingAction` */
export interface PendingAction {
  id: string;
  /** "nl" = natural-language request run by the frontend router; "tool" = a single tool call. */
  kind: string;
  tool: string;
  /** Arguments for kind "tool" (re-validated on approval). */
  args: unknown;
  /** What the user sees. */
  text: string;
  client: string;
  createdMs: number;
  /** pending | approved | declined | done | failed | expired */
  status: string;
  result: string;
  /**
   * For requests raised inside Lens (see [`LOCAL_KINDS`]): the id the owning part of Lens
   * knows the request by (the assistant's call id, a bridge message id, a Lens App release).
   */
  reference?: string;
  /**
   * A ready card for local requests (same shape as `control_preview`); null for MCP requests,
   * whose card is built on demand.
   */
  preview?: unknown;
  /**
   * The one-time approval token for this exact request, issued when it was queued (that is,
   * when its card is shown). Approving must send it back (`approve_action`). It goes to the
   * Lens card only: MCP clients are given the id and status, never this.
   */
  token?: string;
}

/** Rust: `win_plugins::PendingApproval` */
export interface PendingApproval {
  pluginId: string;
  /** "launch:<app path>" or "url:<https origin>" */
  grant: string;
  /** What the user sees, e.g. "open https://example.com". */
  label: string;
}

/** Rust: `coreapps::monitor::PerfRates` */
export interface PerfRates {
  /** Busiest GPU engine, % (what Task Manager shows). None when Windows has no GPU counters. */
  gpuPct: number | null;
  diskReadBps: number | null;
  diskWriteBps: number | null;
  /** % of time the disks were busy (all disks). */
  diskBusyPct: number | null;
  netRxBps: number | null;
  netTxBps: number | null;
}

