/** Rust: `win_workspaces::WorkspacesConfig` */
export interface WorkspacesConfig {
  enabled: boolean;
  /** "auto" | "virtual-desktops" | "groups" */
  mode: string;
  /** When an app with a rule opens, switch to its workspace (true) or leave it there minimised. */
  followAssigned: boolean;
  workspaces: WorkspaceDef[];
}

/** Rust: `mission::plan::WriteAction` */
export type WriteAction =
  | ({ kind: "rerun" } & { runId: number; label: string; })
  | ({ kind: "merge" } & { pr: number; sha: string; method: string; title: string; headRef: string; baseRef: string; files: number; commits: number; })
  | ({ kind: "comment" } & { issue: number; body: string; })
  | ({ kind: "label" } & { issue: number; labels: string[]; })
  | ({ kind: "close" } & { issue: number; note: string; notPlanned: boolean; })
  | ({ kind: "tag" } & { tag: string; sha: string; })
  | ({ kind: "draftPr" } & { branch: string; path: string; content: string; title: string; body: string; })
  | ({ kind: "localDraft" } & { name: string; content: string; })
  | { kind: "syncDevFolder" }
  | { kind: "clearCache" }
  | { kind: "relaunch" }
  | ({ kind: "configSet" } & { path: string; value: string; before: string; });

/** Rust: `mission::plan::WritePlan` */
export interface WritePlan {
  id: string;
  action: string;
  target: string;
  /** What will happen, one line each, in order. */
  steps: string[];
  /** Destructive or hard to undo (merge, tag, close): the page asks twice. */
  heavy: boolean;
}

